                    k = max(current) + 1
                    break  # Restart from highest color
                # Try Kempe chain swaps
                for v in vertices:
                    for c in range(target_color):
                        # BFS to find Kempe chain component for (target_color, c) containing v
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for nb in neighbors[node]:
                                if not visited[nb] and current[nb] in (target_color, c):
                                    visited[nb] = True
                                    queue.append(nb)
                        # Check if swapping the component is safe: after swap, v becomes c, so no neighbor should have color c
                        conflict = False
                        for u in neighbors[v]:
                            if visited[u]:
                                # u in component: color flips
                                new_color_u = target_color if current[u] == c else c
                            else:
                                new_color_u = current[u]
                            if new_color_u == c:
                                conflict = True
                                break
                        if not conflict:
                            # Perform the swap
                            for node in component:
                                if current[node] == target_color:
                                    current[node] = c
                                else:  # must be c
                                    current[node] = target_color
                            made_change = True
                            improved = True
                            break
                    if made_change:
                        break
                if made_change:
                    k = max(current) + 1
                    break
            if not improved:
                break
        return current

    # Apply Kempe reduction to the best coloring found
    final_coloring = kempe_reduce(best_coloring)
    final_num_colors = max(final_coloring) + 1 if final_coloring else 0
    if final_num_colors < best_num_colors:
        best_num_colors = final_num_colors
        best_coloring = final_coloring[:]

    return best_coloring
